public static void main(String[] args) throws IOException {
    int[] crons = new int[6];
    int[] cronss = new int[]{1, 5, 10, 50, 100, 500};
    for (int i = 0; i < 6; i++) {
        crons[i] = nextInt();
    }
    int N = nextInt();
    int[] Xs = new int[N];
    for (int i = 0; i < N; i++) {
        Xs[i] = nextInt();
    }
    for (int X : Xs) {
        for (int i = 5; i >= 0 && X > 0; i--) {
            int cron = X / cronss[i];
            int minUsage = Math.min(cron, crons[i]);
            X -= minUsage * cronss[i];
            crons[i] -= minUsage;
        }
        if (X > 0) {
            System.out.println("No");
            return;
        }
    }
    System.out.println("Yes");

    out.flush();
}
